package education.cccp.academy.workstation

import education.cccp.academy.opencode.OpenCodePlugin

/**
 * One generated file of the learner Gradle project (ACADEMY-16).
 *
 * @property relativePath path relative to the workstation root
 * @property content rendered content
 */
data class WorkstationProjectFile(
    val relativePath: String,
    val content: String,
) {
    init {
        require(relativePath.isNotBlank()) { "relativePath must not be blank" }
        require(content.isNotBlank()) { "content must not be blank" }
    }
}

/**
 * Renders the learner Gradle project that makes the exposed public boroughs
 * **runnable** (ACADEMY-16, D-LWA-4).
 *
 * The catalog is the single source of truth: only plugins with a published
 * version are enabled and applied, so the generated build can never reference
 * an artefact that does not exist (the S-007 `moodle:4.5` lesson). The project
 * is intentionally minimal — a `settings.gradle.kts` resolving from Maven
 * Central and a `build.gradle.kts` applying the enabled plugins. The learner
 * drives it through the opencode tools generated by
 * [education.cccp.academy.opencode.OpenCodeToolGenerator].
 *
 * The `build.gradle.kts` applies the plugins **without** configuring them: the
 * first workstation dogfooding (US-7) is the moment that proves whether the
 * combined plugin set applies cleanly; a conflicting subset can be disabled by
 * blanking a version in the catalog.
 */
object WorkstationProjectGenerator {
    /** Renders the learner project files for the enabled [plugins]. */
    fun render(
        plugins: List<OpenCodePlugin>,
        rootProjectName: String = "academy-workstation",
    ): List<WorkstationProjectFile> {
        val enabled = plugins.filter { it.version.isNotBlank() }
        require(enabled.isNotEmpty()) { "at least one public plugin must be enabled (non-blank version)" }
        require(enabled.map { it.id }.distinct().size == enabled.size) { "enabled plugin ids must be unique" }

        val settings =
            buildString {
                appendLine("// Generated by education.cccp.academy (ACADEMY-16). Do not edit.")
                appendLine("pluginManagement {")
                appendLine("    repositories {")
                appendLine("        mavenCentral()")
                appendLine("        gradlePluginPortal()")
                appendLine("    }")
                appendLine("}")
                appendLine()
                appendLine("dependencyResolutionManagement {")
                appendLine("    repositories {")
                appendLine("        mavenCentral()")
                appendLine("    }")
                appendLine("}")
                appendLine()
                appendLine("rootProject.name = \"$rootProjectName\"")
            }

        val build =
            buildString {
                appendLine("// Generated by education.cccp.academy (ACADEMY-16). Do not edit.")
                appendLine("// Public boroughs enabled in opencode as tools.")
                appendLine("plugins {")
                enabled.forEach { plugin ->
                    appendLine("    id(\"${plugin.id}\") version \"${plugin.version}\"")
                }
                appendLine("}")
            }

        return listOf(
            WorkstationProjectFile("project/settings.gradle.kts", settings),
            WorkstationProjectFile("project/build.gradle.kts", build),
        )
    }
}
